  <div class="row bg-grey-2 q-pl-xl q-pr-md">
    <div class="secondary-c-text text-h6">
      <q-btn flat rounded data-cy="dashboard" color="primary" to="/dashboard">
        <q-icon class="text-red-13" size="sm">
          <Icon icon="mdi:arrow-left" width="24" height="24" />
        </q-icon>
        <label
          style="
            vertical-align: middle;
            margin-left: 10px;
            font-size: 20px;
            cursor: pointer;
          "
          >{{ $t('dashboard') }}</label
        >
      </q-btn>
    </div>
  </div>

  <div class="row bg-grey-2 q-pl-xl q-pr-md q-pb-md">
    <div class="max-width-100" id="left_section" ref="left_section">
      <div class="full-width bg-white q-ma-sm scroll-area-height">
        <div class="row justify-center q-pl-md q-pr-md q-pt-md">
          <span class="secondary-c-text text-h6 text-weight-bold">
            {{ $t('page_number_text') }}
          </span>
        </div>

        <div class="full-width left-scroll-area-height scrolle-y q-pa-sm">
          <img
            v-for="(imageMoc, index) in images"
            :data-id="index"
            :key="index"
            :src="baseUrl + '/' + imageMoc.path + '?' + tokenQueryParam"
            class="q-pa-xs shadow-5 full-width q-ma-sm cursor-pointer"
            :class="index === page - 1 ? 'active' : ''"
            style="height: auto"
            @click="imageclicked"
          />
        </div>
      </div>
    </div>

    <div class="right_section q-pl-sm" id="right_section" ref="right_section">
      <div class="row">
        <div
          class="col-xs-12 col-sm-5 col-md-5 col-lg-5 q-px-sm scroll-area-height"
        >
          <div class="bg-white mb-4 image_control_panel">
            <div class="row">
              <div class="panel-left col-sm-6 col-md-6 col-lg-6">
                <div class="row">
                  <q-btn
                    id="menu_btn"
                    round
                    icon="chevron_right"
                    size="xs"
                    class="text-grey-6 toggler-right p-t-40"
                    @click="toggleMenu()"
                  />
                  {{ apiData.filename }}
                </div>
              </div>
              <div class="panel-middle col-sm-1 col-md-1 col-lg-1 mt-8">
                <span class="page-numbers"
                  >{{ currentPage() }}/{{ images.length }}</span
                >
              </div>
              <div class="panel-right col-sm-5 col-md-5 col-lg-5">
                <q-btn
                  flat
                  class="float-right pr-6 pl-6"
                  @click="viewOCRDocument"
                >
                  <Icon icon="mdi:text-recognition" width="24" height="24" />
                  <q-tooltip>{{ $t('ocr_view') }}</q-tooltip>
                </q-btn>
                <q-btn
                  flat
                  id="glassBtn"
                  class="float-right pr-6 pl-6"
                  @click="startMagnifyGlass"
                >
                  <Icon icon="mdi:magnify" width="24" height="24" />
                  <q-tooltip>{{ $t('magnify') }}</q-tooltip>
                </q-btn>
              </div>
            </div>
          </div>
          <div
            class="full-width bg-white"
            id="image_container"
            style="height: 90%"
          >
            <div
              class="full-width full-height q-pa-sm scrolle-y"
              id="image_scrolle"
              style="position: relative"
            >
              <div
                id="zoom"
                :style="
                  'background-image: url(&quot;' +
                  image +
                  ' &quot;); top: 51px;left: 506px; background-position: 268.297px 82.6934px;'
                "
              ></div>

              <img
                class="screenshot"
                :src="image + '?' + tokenQueryParam"
                :width="imageWidth"
                id="screenshot"
                ref="screenshot"
                draggable="false"
                @load="getImageDetails"
              />
            </div>
          </div>
        </div>

        <!--Medi Fields Start-->
        <div class="col-xs-12 col-sm-7 col-md-7 col-lg-7">
          <template v-if="hasApiData()">
            <MediFieldsView :data="apiData" :renderOpenWindoIcon="true" />
          </template>
        </div>
        <!--Medi Fields END-->
      </div>
    </div>
  </div>

  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import axios from 'axios';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import Loader from '../components/Loader.vue';
import { DOC2API_URL } from 'src/pages/APIs';
import helperMixin from '../mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { dynamicObj } from './assets';
import { api, getAuthorizationToken } from 'pages/APIs';
import { useQuasar } from 'quasar';
import { objLen } from 'src/utils/general';
import { documentDetailApiService } from 'src/services';
import { cleanUpImagesUrl, cleanUpImagePath } from 'src/utils/viewImages';
import { allowedDocTypes, readOnlyDocStatus } from 'src/constants';
import MediFieldsView from 'src/components/MediFieldsView.vue';
import { useImageAuth } from 'src/composables/useImageAuth';

const $ = document.querySelector.bind(document);
let screenshot: HTMLElement;
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  components: {
    Loader,
    MediFieldsView,
    
  },
  watch: {},
  data() {
    return {
      page: 1,
      docId: '',
      imageHeight: 0,
      imageWidth: 0,
      showArticlePage: false,
      loading: false,
      enableExportButton: false,
      magnifyGlass: {} as any,
      allowedDoctypes: allowedDocTypes,
      account_block: '',
    };
  },
  beforeRouteLeave: function (to: any, from: any, next: any) {
    // Before leaving this page, lets first reset everything
    this.removeMagnifier();
    next();
  },
  mounted: function () {
    window.addEventListener('resize', this.windowResize);
    document.body.addEventListener('click', this.mouseClicked, true);
    $('#image_scrolle')!.addEventListener('scroll', this.handleScroll);

    this.init();
  },
  unmounted: function () {
    window.removeEventListener('resize', this.windowResize);
  },
  methods: {
    async init() {
      if (!this.$route.params.id) {
        this.$router.push('/dashboard');
      }
      this.docId = this.$route.params.id as string;
      await this.getInvoiceDataByDocId(this.docId);

      if (readOnlyDocStatus.includes(this.apiData.status)) {
        this.isReadOnly = true;
      }
      this.initPage();
    },
    // TODO::Permission  acls needs to be applied here
    async getInvoiceDataByDocId(docId: string) {
      try {
        this.showLoading();
        const data = {
          doc_id: docId,
        };
        const response = await documentDetailApiService.getById(data);
        if (response.doc_id) {
          this.apiData = response;
        } else {
          notify.error(this.$t('INVALID_DOCUMENT'));
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    goHelp() {
      window.open('https://docs.cloudintegration.eu/');
    },
    initPage() {
      this.handleImageBaseURL();
      this.image =
        this.baseUrl + '/' + cleanUpImagePath(this.apiData.images[0].path);
      this.images = cleanUpImagesUrl(this.apiData.images);

      this.handleLineItemsVisibilty();

      // set the width of image
      let imageElm = $('#image_container') as HTMLElement;
      this.imageWidth = imageElm.offsetWidth;
      this.imageHeight = imageElm.offsetHeight;
    },

    handleLineItemsVisibilty() {
      const APP_VUE_TABLE_EXTRACTION = process.env.APP_VUE_TABLE_EXTRACTION
        ? process.env.APP_VUE_TABLE_EXTRACTION.toString()
        : 'false';

      if (
        APP_VUE_TABLE_EXTRACTION.toLowerCase() === 'true' &&
        this.allowedDoctypes.indexOf(this.apiData.doc_type) !== -1
      ) {
        //this.showArticlePage = true;
      }

      this.account_block = '';
      if (
        (this.apiData.hasOwnProperty('table_blocked') &&
          this.apiData.table_blocked == true) ||
        this.apiData.table_blocked == 'true'
      ) {
        this.account_block = 'table_blocked';
        this.showArticlePage = false;
      }

      if (
        (this.apiData.hasOwnProperty('table_extraction_disabled') &&
          this.apiData.table_extraction_disabled == true) ||
        this.apiData.table_extraction_disabled == 'true'
      ) {
        this.account_block = 'table_extraction_disabled';
        this.showArticlePage = false;
      }

      if (
        (this.apiData.hasOwnProperty('table_not_supported') &&
          this.apiData.table_not_supported == true) ||
        this.apiData.table_not_supported == 'true'
      ) {
        this.account_block = 'table_not_supported';
        this.showArticlePage = false;
      }
    },
    imageclicked(evt: any) {
      this.image =
        this.baseUrl +
        '/' +
        cleanUpImagePath(this.apiData.images[evt.target.dataset.id].path);
      // getImageDetails function will be auto called by load event of image. as image is changed.
      this.page = parseInt(evt.target.dataset.id) + 1;
    },
    updateImportJson(
      connectionId: string,
      coordinates?: any,
      page?: number,
      extractionMethod?: string,
    ) {
      let found = false;

      this.apiData.fields.forEach((value: any, index: any) => {
        if (value.name === connectionId) {
          found = true;

          if (!value.hasOwnProperty('original')) {
            value['original'] = Object.assign({}, value);
          }
          if (coordinates) {
            value.coords = coordinates;
          }
          if (page) {
            value.page = page;
          }

          value.is_valid = true;
          value.is_validated = true;

          let field = this.fields[connectionId];
          value.formatted_value = field.formatted_value;
          value.value = field.value;
          value.content = field.content;
          if (!(field.hasOwnProperty('api_save') && field.api_save)) {
            value.value = field.formatted_value;
          }

          value.color = 'success-border-left';

          // value.confidence = 0.99;
          return;
        }
      });
      if (!found) {
        this.apiData.fields.push({});
        this.apiData.fields[this.apiData.fields.length - 1].name = connectionId;
        this.apiData.fields[this.apiData.fields.length - 1].content =
          this.fields[connectionId].content;
        // this.apiData.fields[this.apiData.fields.length - 1].confidence = 0.99;
        this.apiData.fields[this.apiData.fields.length - 1].formatted_value =
          this.fields[connectionId].formatted_value;
        this.apiData.fields[this.apiData.fields.length - 1].value =
          this.fields[connectionId].value;
        this.apiData.fields[this.apiData.fields.length - 1].validation_code =
          '';
        this.apiData.fields[this.apiData.fields.length - 1].extraction_method =
          extractionMethod;
        this.apiData.fields[this.apiData.fields.length - 1].is_validated = true;
        this.apiData.fields[this.apiData.fields.length - 1].is_valid = true;
        this.apiData.fields[this.apiData.fields.length - 1].color =
          'success-border-left';

        if (coordinates) {
          this.apiData.fields[this.apiData.fields.length - 1].coords =
            coordinates;
        }

        if (page) {
          this.apiData.fields[this.apiData.fields.length - 1].page = page;
        }
      }
    },
    convertToUSValue(value: string) {
      return value.replace(/,/g, '.');
    },
    convertToDeValue(value: string) {
      return value.toString().replace(/\./g, ',');
    },
    setApiData(data: any) {
      this.apiData = data;
      this.$forceUpdate();
    },

    windowResize() {
      let imageElm = $('#image_container') as HTMLElement;
      this.imageWidth = imageElm.offsetWidth;
      this.imageHeight = imageElm.offsetHeight;
      this.$forceUpdate();

      setTimeout(() => {
        this.getImageDetails();
        this.removeMagnifier();
      }, 20);
    },
    handleScroll() {
      logInfo('hell');
    },
    getImageDetails() {
      screenshot = $('#screenshot') as HTMLElement;
      if (screenshot) {
        this.imageWidth = screenshot.offsetWidth;
        this.imageHeight = screenshot.offsetHeight;
      }
      this.toggleMenu();
    },
    startMagnifyGlass(event: any) {
      let glass = document.getElementById('zoom') as HTMLElement;
      if (glass.classList.contains('enable-glass')) {
        return;
      }
      let screenshot = $('.screenshot') as HTMLImageElement;
      const glassBtn: HTMLElement | null = $('#glassBtn');
      glassBtn!.classList.add('glass-active');
      glass.classList.add('enable-glass');
      glass.style.backgroundImage = 'url(' + screenshot.src + ')';

      this.magnifyGlass = {
        Ix: screenshot.offsetLeft,
        Iy: screenshot.offsetTop,
        Zw: glass.offsetWidth,
        Zh: glass.offsetHeight,
        ratio: screenshot.naturalWidth / screenshot.width,
      };

      screenshot.addEventListener('pointermove', this.updateMagnifier);
      glass.addEventListener('pointermove', this.updateMagnifier);
    },
    updateMagnifier(event: any) {
      let glass = document.getElementById('zoom') as HTMLElement;
      if (!glass.classList.contains('enable-glass')) {
        logInfo('magnify glass not enable');
        return;
      }
      var pos, x, y;
      /*prevent any other actions that may occur when moving over the image*/
      event.preventDefault();
      /*get the cursor's x and y positions:*/
      pos = this.getCursorPos(event);
      x = pos.x;
      y = pos.y;
      document.body.classList.add('active');
      let yfactor = 50;
      let xfactor = 20;
      let imgFactorX = xfactor;
      let imgFactorY = yfactor + 30;

      glass.style.top = pos.y - this.magnifyGlass.Zh / 2 + yfactor + 'px';
      glass.style.left = pos.x - this.magnifyGlass.Zw / 2 + xfactor + 'px';

      let imgX =
        (this.magnifyGlass.Ix - x) * this.magnifyGlass.ratio +
        this.magnifyGlass.Zw / 2 -
        imgFactorX;
      let imgY =
        (this.magnifyGlass.Iy - y) * this.magnifyGlass.ratio +
        this.magnifyGlass.Zh / 2 -
        imgFactorY;
      let calculatedPosition = imgX + 'px ' + imgY + 'px';
      glass.style.backgroundPosition = calculatedPosition;
    },
    getCursorPos(e: any) {
      var a,
        x = 0,
        y = 0;
      e = e || window.event;
      /*get the x and y positions of the image:*/
      let img = $('.screenshot') as HTMLImageElement;
      a = img.getBoundingClientRect();
      /*calculate the cursor's x and y coordinates, relative to the image:*/
      x = e.pageX - a.left;
      y = e.pageY - a.top;
      /*consider any page scrolling:*/
      x = x - window.pageXOffset;
      y = y - window.pageYOffset;
      return { x: x, y: y };
    },
    removeMagnifier() {
      const glassBtn: HTMLElement | null = $('#glassBtn');
      if (glassBtn) {
        glassBtn.classList.remove('glass-active');
      }

      const glass = document.getElementById('zoom') as HTMLElement;
      if (glass) {
        glass.classList.remove('enable-glass');
        glass.removeEventListener('pointermove', this.updateMagnifier, false);
      }

      let screenshot = $('.screenshot') as HTMLImageElement;
      if (screenshot) {
        screenshot.removeEventListener(
          'pointermove',
          this.updateMagnifier,
          false,
        );
      }

      document.body.classList.remove('active');
      this.magnifyGlass = null;
    },
    mouseClicked(e: any) {
      this.removeMagnifier();
    },
    currentPage() {
      return this.page;
    },
    handleImageBaseURL() {
      if (!this.apiData.images[0]) {
        return;
      }
      if (this.apiData.images[0].path.match(/doc2/g)) {
        this.baseUrl = DOC2API_URL;
      }
    },

    hasApiData() {
      return objLen(this.apiData) !== 0;
    },
    viewOCRDocument() {
      let route = this.$router.resolve({
        path: '/ocr-document/' + this.docId + '/' + this.page,
      });
      window.open(
        route.href,
        '_blank',
        'location=yes,toolbar=yes,scrollbars=yes,resizable=yes,left=500,width=1500,height=1000',
      );
    },
    toFlowScreen(doc_id: string) {
      this.$router.push('/doc_flow/' + doc_id);
    },
  },
  setup() {
    const $q = useQuasar();
    let fieldsObjArray: any = {};
    let data: any = [];

    const { tokenQueryParam } = useImageAuth();
    return {
      tokenQueryParam: tokenQueryParam,
      apiData: ref(data),
      fields: fieldsObjArray,
      image: '',
      images: data,
      baseUrl: DOC2API_URL,
      isReadOnly: false,
      showNotification(message: string) {
        notify.info(message);
      },
    };
  },
});
</script>

